import { useState } from 'react';
import {
  JxChip,
  JxBadge,
  JxCircularProgress,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type Status = 'active' | 'paused' | 'over-budget' | 'completed';

interface Project {
  id: string;
  name: string;
  status: Status;
  quotaPercent: number;
}

const STATUS_ORDER: Status[] = ['active', 'paused', 'over-budget', 'completed'];

const STATUS_LABELS: Record<Status, string> = {
  active: 'Активен',
  paused: 'На паузе',
  'over-budget': 'Превышена квота',
  completed: 'Завершён',
};

const STATUS_BADGE_VARIANT: Record<Status, 'success' | 'warning' | 'danger' | 'neutral'> = {
  active: 'success',
  paused: 'neutral',
  'over-budget': 'danger',
  completed: 'warning',
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Payments API', status: 'active', quotaPercent: 42 },
  { id: 'p2', name: 'Mobile App', status: 'over-budget', quotaPercent: 118 },
  { id: 'p3', name: 'Marketing Site', status: 'completed', quotaPercent: 100 },
  { id: 'p4', name: 'Data Pipeline', status: 'active', quotaPercent: 67 },
  { id: 'p5', name: 'Internal Tools', status: 'paused', quotaPercent: 30 },
  { id: 'p6', name: 'Design System', status: 'active', quotaPercent: 55 },
  { id: 'p7', name: 'Support Portal', status: 'over-budget', quotaPercent: 132 },
  { id: 'p8', name: 'Analytics Dashboard', status: 'completed', quotaPercent: 100 },
  { id: 'p9', name: 'Onboarding Flow', status: 'paused', quotaPercent: 12 },
  { id: 'p10', name: 'Search Service', status: 'active', quotaPercent: 78 },
  { id: 'p11', name: 'Billing Engine', status: 'over-budget', quotaPercent: 145 },
  { id: 'p12', name: 'Notification Hub', status: 'active', quotaPercent: 89 },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [selectedStatuses, setSelectedStatuses] = useState<Status[]>(STATUS_ORDER);
  const [page, setPage] = useState(1);

  const selectStatus = (status: Status) => {
    setSelectedStatuses((prev) => (prev.includes(status) ? prev : [...prev, status]));
    setPage(1);
  };

  const removeStatus = (status: Status) => {
    setSelectedStatuses((prev) => prev.filter((s) => s !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setSelectedStatuses(STATUS_ORDER);
    setPage(1);
  };

  const filtered = PROJECTS.filter((p) => selectedStatuses.includes(p.status));
  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const pageItems = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-lg)' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-sm)' }}>
        {STATUS_ORDER.map((status) => {
          const isSelected = selectedStatuses.includes(status);
          return isSelected ? (
            <JxChip
              key={status}
              variant="primary"
              removable
              onRemove={() => removeStatus(status)}
            >
              {STATUS_LABELS[status]}
            </JxChip>
          ) : (
            <JxChip key={status} variant="ghost" onClick={() => selectStatus(status)}>
              {STATUS_LABELS[status]}
            </JxChip>
          );
        })}
      </div>

      {pageItems.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          description="Попробуйте выбрать другой статус или сбросьте фильтры"
        >
          <JxButton variant="secondary" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        </JxEmptyState>
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-sm)' }}>
            {pageItems.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-md)',
                  padding: 'var(--jx-space-md)',
                  borderBottom: '1px solid var(--jx-color-border)',
                }}
              >
                <span style={{ fontWeight: 'var(--jx-font-weight-medium)' }}>{project.name}</span>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-md)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-xs)' }}>
                    <JxCircularProgress
                      value={project.quotaPercent}
                      max={100}
                      size="sm"
                      aria-label={`Квота заполнена на ${project.quotaPercent}%`}
                    />
                    <span>{project.quotaPercent}%</span>
                  </div>
                  <JxBadge variant={STATUS_BADGE_VARIANT[project.status]}>
                    {STATUS_LABELS[project.status]}
                  </JxBadge>
                </div>
              </div>
            ))}
          </div>

          <JxPagination
            value={page}
            onValueChange={setPage}
            pageCount={pageCount}
          />
        </>
      )}
    </div>
  );
}

